async function download(url){const r=await fetch(url,{signal:AbortSignal.timeout(18000)});if(!r.ok)throw new Error(`Upstream ${r.status}`);return r;}
async function rates(){if(ratesCache&&Date.now()-ratesCache.fetched<3600000)return ratesCache;const xml=await(await download('https://www.cbr.ru/scripts/XML_daily.asp')).text(),values={RUB:1};for(const m of xml.matchAll(/<Valute\b[^>]*>[\s\S]*?<\/Valute>/g)){const code=m[0].match(/<CharCode>(.*?)<\/CharCode>/)?.[1],v=m[0].match(/<Value>(.*?)<\/Value>/)?.[1],n=m[0].match(/<Nominal>(.*?)<\/Nominal>/)?.[1];if(code&&v&&n)values[code]=Number(v.replace(',','.'))/Number(n);}ratesCache={values,date:xml.match(/Date="([^"]+)"/)?.[1]||null,fetched:Date.now()};return ratesCache;}
export async function freshData(region){const config=regions.find(r=>r.code===region);if(!config)throw new Error('Unknown region');const [search,featured,fx]=await Promise.allSettled([download(`https://store.steampowered.com/search/results/?query=&start=0&count=100&specials=1&category1=998&cc=${region}&l=russian&infinite=1`).then(r=>r.json()),download(`https://store.steampowered.com/api/featuredcategories/?cc=${region}&l=russian`).then(r=>r.json()),rates()]);const games=search.status==='fulfilled'?parseGames(search.value.results_html||''):[];if(featured.status==='fulfilled')for(const g of featured.value.specials?.items||[]){if(g.currency!==config.currency||!g.discount_percent)continue;const old=games.find(x=>x.id===g.id);if(old)old.ends=g.discount_expiration||null;else games.push({id:g.id,name:g.name,price:g.final_price/100,original:g.original_price/100,discount:g.discount_percent,image:g.small_capsule_image,ends:g.discount_expiration||null,windows:g.windows_available,mac:g.mac_available,linux:g.linux_available});}if(!games.length)throw new Error('No discounts received');return{games:[...new Map(games.filter(g=>g.price>0&&g.price<g.original).map(g=>[g.id,g])).values()],updated:new Date().toISOString(),rate:config.currency==='RUB'?1:fx.status==='fulfilled'?fx.value.values[config.currency]||null:null,rateDate:fx.status==='fulfilled'?fx.value.date:null,region:region.toUpperCase(),currency:config.currency,country:config.name,source:'Steam',stale:false};}
export default{async fetch(request){const url=new URL(request.url);if(url.pathname==='/api/sales'){const region=(url.searchParams.get('region')||'kz').toLowerCase();if(!regions.some(r=>r.code===region))return Response.json({error:'Неизвестный регион'},{status:400});const old=recent.get(region);if(old&&Date.now()-new Date(old.updated).getTime()<300000)return Response.json(old,{headers:{'Cache-Control':'no-store'}});try{if(!pending.has(region))pending.set(region,freshData(region));const result=await pending.get(region);recent.set(region,result);return Response.json(result,{headers:{'Cache-Control':'no-store'}});}catch(error){console.error('Steam fetch failed',region,error.message);const fallback=old||SNAPSHOTS[region];return fallback?Response.json({...fallback,stale:true},{headers:{'Cache-Control':'no-store'}}):Response.json({error:'Steam временно недоступен'},{status:502});}finally{pending.delete(region);}}const path=url.pathname==='/'?'/index.html':url.pathname,asset=ASSETS[path];if(!asset)return new Response('Not found',{status:404});return new Response(asset.body,{headers:{'Content-Type':asset.type,'Cache-Control':'no-cache','X-Content-Type-Options':'nosniff'}});}};
